#include "SessionCalibrationVerifier.h"
namespace dnxr { SessionCalibrationResult SessionCalibrationVerifier::verify(const SessionCalibrationInputs& i) const { if(!i.patientIdentity)return{false,"patient_identity_missing"}; if(!i.deviceIdentity)return{false,"device_identity_missing"}; if(!i.calibrationFresh)return{false,"calibration_stale"}; if(!i.baselineStable)return{false,"baseline_drift"}; if(!i.stopSignal)return{false,"stop_signal_failed"}; if(!i.realityAnchor)return{false,"reality_anchor_failed"}; if(!i.physicianConfirmation)return{false,"physician_confirmation_missing"}; return{true,"session_calibration_verified"}; } }
